from pathlib import Path


def serve_asset(site_root: Path, name: str) -> bytes:
    """Return the bytes of a published asset below the site root."""
    if any(part.startswith(".") for part in Path(name).parts):
        raise PermissionError(f"hidden asset refused: {name}")
    return (site_root / name).read_bytes()
